adcs_vec3_t momentum_nms = {0, 0, 0};
adcs_vec3_t error_nms = {0, 0, 0};
adcs_vec3_t torque_nm = {0, 0, 0};
adcs_vec3_t target_error = {0, 0, 0};
double err_norm = 0.0;
unint32 i = 0;
int target_changed = 0;
int valid = 1;
double vals[3];

mb_output.mode = mb_state.mode;
mb_output.settled = mb_state.settled;
mb_output.saturation_mask = 0U;
mb_output.momentum_nms = momentum_nms;
mb_output.commanded_target_nms = mb_state.commanded_target_nms;
mb_output.error_nms = error_nms;
mb_output.integral_error_nms_s = mb_state.integral_error_nms_s;
mb_output.torque_nm = torque_nm;

if ((mb_input.enable != 0) && (mb_input.enable != 1)) {
    valid = 0;
} else if (mb_input.enable == 1) {
    if ((mb_input.wheels == NULL) || (mb_input.wheel_count != 4U)) {
        valid = 0;
    } else {
        for (i = 0; i < mb_input.wheel_count; i++) {
            if ((!isfinite(mb_input.wheels[i].inertia_kg_m2)) ||
                (mb_input.wheels[i].inertia_kg_m2 < 0.0) ||
                (!isfinite(mb_input.wheels[i].speed_rad_s)) ||
                (fabs(mb_input.wheels[i].speed_rad_s) > mb_config.max_wheel_speed_rad_s) ||
                (!isfinite(mb_input.wheels[i].axis_body.x)) ||
                (!isfinite(mb_input.wheels[i].axis_body.y)) ||
                (!isfinite(mb_input.wheels[i].axis_body.z))) {
                valid = 0;
                break;
            }
        }
    }
    if (valid) {
        if ((!isfinite(mb_config.target_nms.x)) || (!isfinite(mb_config.target_nms.y)) ||
            (!isfinite(mb_config.target_nms.z)) ||
            (!isfinite(mb_config.target_slew_nms_per_cycle)) ||
            (!isfinite(mb_config.enter_error_nms)) || (!isfinite(mb_config.exit_error_nms)) ||
            (!isfinite(mb_config.kp_s_inv)) || (!isfinite(mb_config.ki_s2_inv)) ||
            (!isfinite(mb_config.dt_s)) || (!isfinite(mb_config.integral_limit_nms_s)) ||
            (!isfinite(mb_config.torque_limit_nm)) ||
            (!isfinite(mb_config.max_wheel_speed_rad_s))) {
            valid = 0;
        } else if ((mb_config.enter_error_nms < 0.0) ||
                   (mb_config.enter_error_nms >= mb_config.exit_error_nms) ||
                   (mb_config.target_slew_nms_per_cycle <= 0.0) || (mb_config.dt_s <= 0.0) ||
                   (mb_config.integral_limit_nms_s <= 0.0) ||
                   (mb_config.torque_limit_nm <= 0.0) ||
                   (mb_config.max_wheel_speed_rad_s <= 0.0) ||
                   (mb_config.settle_cycles < 1U) || (mb_config.settle_cycles > 20U) ||
                   (mb_config.kp_s_inv < 0.0) || (mb_config.ki_s2_inv < 0.0)) {
            valid = 0;
        }
    }
    if (valid) {
        if (adcs_wheel_momentum(mb_input.wheels, mb_input.wheel_count, &momentum_nms) != ADCS_OK) {
            valid = 0;
        }
    }
}

if (mb_input.enable == 0) {
    mb_state.mode = MB_OFF;
    mb_state.settled = 0;
    mb_state.target_initialized = 0;
    mb_state.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.mode = MB_OFF;
    mb_output.settled = 0;
    mb_output.saturation_mask = 0U;
    mb_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    return;
}

if (!valid) {
    mb_state.mode = MB_FAULT;
    mb_state.settled = 0;
    mb_state.target_initialized = 0;
    mb_state.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
