    mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    return;
}

if (!mb_state.target_initialized) {
    mb_state.commanded_target_nms = momentum_nms;
    mb_state.target_initialized = 1;
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_state.settled = 0;
    mb_state.mode = MB_RAMP;
}

target_error = adcs_vec3_sub(&mb_config.target_nms, &mb_state.commanded_target_nms);
target_changed = 0;
vals[0] = mb_state.commanded_target_nms.x;
vals[1] = mb_state.commanded_target_nms.y;
vals[2] = mb_state.commanded_target_nms.z;
{
    double te[3];
    te[0] = target_error.x;
    te[1] = target_error.y;
    te[2] = target_error.z;
    for (i = 0; i < 3U; i++) {
        double step = mb_config.target_slew_nms_per_cycle;
        if (te[i] > step) {
            vals[i] += step;
            target_changed = 1;
        } else if (te[i] < -step) {
            vals[i] -= step;
            target_changed = 1;
        } else if (te[i] != 0.0) {
            vals[i] += te[i];
            target_changed = 1;
        }
    }
}
mb_state.commanded_target_nms = (adcs_vec3_t){vals[0], vals[1], vals[2]};

error_nms = adcs_vec3_sub(&momentum_nms, &mb_state.commanded_target_nms);
err_norm = adcs_vec3_norm(&error_nms);

if (target_changed) {
    mb_state.mode = MB_RAMP;
    mb_state.settled = 0;
} else if (mb_state.mode == MB_RAMP) {
    if (err_norm <= mb_config.enter_error_nms) {
        mb_state.mode = MB_BIAS;
        mb_state.settled = 0;
    }
} else if (mb_state.mode == MB_BIAS) {
    if (err_norm <= mb_config.enter_error_nms) {
        mb_state.settled += 1U;
        if (mb_state.settled >= mb_config.settle_cycles) {
            mb_state.mode = MB_HOLD;
        }
    } else {
        mb_state.settled = 0U;
    }
} else if (mb_state.mode == MB_HOLD) {
    if (err_norm >= mb_config.exit_error_nms) {
        mb_state.mode = MB_BIAS;
        mb_state.settled = 0U;
    }
}

{
    double ex = error_nms.x, ey = error_nms.y, ez = error_nms.z;
    double ix = mb_state.integral_error_nms_s.x;
    double iy = mb_state.integral_error_nms_s.y;
    double iz = mb_state.integral_error_nms_s.z;
    double old_ix = ix, old_iy = iy, old_iz = iz;
    double pi_x, pi_y, pi_z;
    double tor_x, tor_y, tor_z;
