    if (mb_state.mode == MB_RAMP) {
        ix = 0.0;
        iy = 0.0;
        iz = 0.0;
    } else {
        ix = ix + ex * mb_config.dt_s;
        iy = iy + ey * mb_config.dt_s;
        iz = iz + ez * mb_config.dt_s;
        if (ix > mb_config.integral_limit_nms_s) ix = mb_config.integral_limit_nms_s;
        if (ix < -mb_config.integral_limit_nms_s) ix = -mb_config.integral_limit_nms_s;
        if (iy > mb_config.integral_limit_nms_s) iy = mb_config.integral_limit_nms_s;
        if (iy < -mb_config.integral_limit_nms_s) iy = -mb_config.integral_limit_nms_s;
        if (iz > mb_config.integral_limit_nms_s) iz = mb_config.integral_limit_nms_s;
        if (iz < -mb_config.integral_limit_nms_s) iz = -mb_config.integral_limit_nms_s;
    }

    prop_x = -mb_config.kp_s_inv * ex;
    prop_y = -mb_config.kp_s_inv * ey;
    prop_z = -mb_config.kp_s_inv * ez;

    pi_x = prop_x - mb_config.ki_s2_inv * ix;
    pi_y = prop_y - mb_config.ki_s2_inv * iy;
    pi_z = prop_z - mb_config.ki_s2_inv * iz;

    mb_output.saturation_mask = 0U;
    if (fabs(pi_x) > mb_config.torque_limit_nm) mb_output.saturation_mask |= 1U;
    if (fabs(pi_y) > mb_config.torque_limit_nm) mb_output.saturation_mask |= 2U;
    if (fabs(pi_z) > mb_config.torque_limit_nm) mb_output.saturation_mask |= 4U;

    if ((mb_output.saturation_mask & 1U) != 0U) {
        double frozen_x = prop_x - mb_config.ki_s2_inv * old_ix;
        if (((pi_x > 0.0) && (frozen_x > pi_x)) ||
            ((pi_x < 0.0) && (frozen_x < pi_x))) {
            ix = old_ix;
            pi_x = frozen_x;
        }
    }
    if ((mb_output.saturation_mask & 2U) != 0U) {
        double frozen_y = prop_y - mb_config.ki_s2_inv * old_iy;
        if (((pi_y > 0.0) && (frozen_y > pi_y)) ||
            ((pi_y < 0.0) && (frozen_y < pi_y))) {
            iy = old_iy;
            pi_y = frozen_y;
        }
    }
    if ((mb_output.saturation_mask & 4U) != 0U) {
        double frozen_z = prop_z - mb_config.ki_s2_inv * old_iz;
        if (((pi_z > 0.0) && (frozen_z > pi_z)) ||
            ((pi_z < 0.0) && (frozen_z < pi_z))) {
            iz = old_iz;
            pi_z = frozen_z;
        }
    }

    mb_state.integral_error_nms_s = (adcs_vec3_t){ix, iy, iz};

    tor_x = pi_x;
    tor_y = pi_y;
    tor_z = pi_z;
    if (tor_x > mb_config.torque_limit_nm) tor_x = mb_config.torque_limit_nm;
    if (tor_x < -mb_config.torque_limit_nm) tor_x = -mb_config.torque_limit_nm;
    if (tor_y > mb_config.torque_limit_nm) tor_y = mb_config.torque_limit_nm;
    if (tor_y < -mb_config.torque_limit_nm) tor_y = -mb_config.torque_limit_nm;
    if (tor_z > mb_config.torque_limit_nm) tor_z = mb_config.torque_limit_nm;
    if (tor_z < -mb_config.torque_limit_nm) tor_z = -mb_config.torque_limit_nm;
    torque_nm = (adcs_vec3_t){tor_x, tor_y, tor_z};
}

mb_output.mode = mb_state.mode;
mb_output.settled = mb_state.settled;
mb_output.momentum_nms = momentum_nms;
mb_output.commanded_target_nms = mb_state.commanded_target_nms;
mb_output.error_nms = error_nms;
mb_output.integral_error_nms_s = mb_state.integral_error_nms_s;
mb_output.torque_nm = torque_nm;

