}
if (valid) {
    for (i = 0; i < 4U; i++) {
        double s = mb_input.wheels[i].speed_rad_s;
        adcs_vec3_t axis;
        if ((!isfinite(s)) || (fabs(s) > mb_config.max_wheel_speed_rad_s)) {
            valid = 0;
            break;
        }
        if ((!isfinite(mb_input.wheels[i].inertia_kg_m2)) ||
            (mb_input.wheels[i].inertia_kg_m2 < 0.0)) {
            valid = 0;
            break;
        }
        if (adcs_vec3_normalize(&mb_input.wheels[i].axis_body, ADCS_EPS_NORM, &axis) !=
            ADCS_OK) {
            valid = 0;
            break;
        }
    }
}
if (valid) {
    if ((!isfinite(mb_config.target_nms.x)) || (!isfinite(mb_config.target_nms.y)) ||
        (!isfinite(mb_config.target_nms.z))) {
        valid = 0;
    }
}
if (valid) {
    if ((!isfinite(kp)) || (kp < 0.0) || (!isfinite(ki)) || (ki < 0.0)) {
        valid = 0;
    }
}
if (valid) {
    if ((!isfinite(mb_config.enter_error_nms)) || (!isfinite(mb_config.exit_error_nms)) ||
        (!(mb_config.enter_error_nms >= 0.0)) ||
        (!(mb_config.enter_error_nms < mb_config.exit_error_nms))) {
        valid = 0;
    }
}
if (valid) {
    if ((!isfinite(slew)) || (!(slew > 0.0)) || (!isfinite(dt)) || (!(dt > 0.0)) ||
        (!isfinite(ilim)) || (!(ilim > 0.0)) || (!isfinite(tlim)) || (!(tlim > 0.0)) ||
        (!isfinite(mb_config.max_wheel_speed_rad_s)) ||
        (!(mb_config.max_wheel_speed_rad_s > 0.0))) {
        valid = 0;
    }
}
if (valid) {
    if ((mb_config.settle_cycles < 1U) || (mb_config.settle_cycles > 20U)) {
        valid = 0;
    }
}

if (!valid) {
    mb_state.mode = MB_FAULT;
    mb_state.settled = 0U;
    mb_output.mode = MB_FAULT;
    mb_output.settled = 0U;
    mb_output.saturation_mask = 0U;
    mb_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    return;
}

if (mb_input.enable == 0) {
    mb_state.mode = MB_OFF;
    mb_state.settled = 0U;
    mb_state.target_initialized = 0;
    mb_state.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.mode = MB_OFF;
    mb_output.settled = 0U;
    mb_output.saturation_mask = 0U;
    mb_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    return;
}

(void)adcs_wheel_momentum(mb_input.wheels, mb_input.wheel_count, &momentum);

if (!mb_state.target_initialized) {
    mb_state.commanded_target_nms = momentum;
    mb_state.target_initialized = 1;
    mb_state.mode = MB_RAMP;
    mb_state.settled = 0U;
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
}

vals_old[0] = mb_state.commanded_target_nms.x;
vals_old[1] = mb_state.commanded_target_nms.y;
vals_old[2] = mb_state.commanded_target_nms.z;
{
    double tgt[3];
    tgt[0] = mb_config.target_nms.x;
    tgt[1] = mb_config.target_nms.y;
    tgt[2] = mb_config.target_nms.z;
    for (i = 0; i < 3U; i++) {
        double diff = tgt[i] - vals_old[i];
        if (diff > slew) {
            vals_new[i] = vals_old[i] + slew;
        } else if (diff < -slew) {
            vals_new[i] = vals_old[i] - slew;
        } else {
            vals_new[i] = tgt[i];
        }
    }
}
new_target = (adcs_vec3_t){vals_new[0], vals_new[1], vals_new[2]};

target_changed = 0;
if ((vals_new[0] != vals_old[0]) || (vals_new[1] != vals_old[1]) ||
    (vals_new[2] != vals_old[2])) {
    target_changed = 1;
}

if (target_changed) {
    if ((mb_state.mode == MB_BIAS) || (mb_state.mode == MB_HOLD)) {
        mb_state.mode = MB_RAMP;
        mb_state.settled = 0U;
    }
}

mb_state.commanded_target_nms = new_target;
err = adcs_vec3_sub(&momentum, &mb_state.commanded_target_nms);

err_norm = adcs_vec3_norm(&err);
switch (mb_state.mode) {
case MB_RAMP:
    if ((vals_new[0] == mb_config.target_nms.x) &&
        (vals_new[1] == mb_config.target_nms.y) &&
        (vals_new[2] == mb_config.target_nms.z)) {
        mb_state.mode = MB_BIAS;
        mb_state.settled = 0U;
    }
    break;
case MB_BIAS:
    if (isfinite(err_norm) && (err_norm <= mb_config.enter_error_nms)) {
        mb_state.settled = mb_state.settled + 1U;
        if (mb_state.settled >= mb_config.settle_cycles) {
            mb_state.mode = MB_HOLD;
        }
    } else {
        mb_state.settled = 0U;
    }
    break;
case MB_HOLD:
    if (isfinite(err_norm) && (err_norm >= mb_config.exit_error_nms)) {
        mb_state.mode = MB_BIAS;
        mb_state.settled = 0U;
    }
    break;
default:
    mb_state.mode = MB_RAMP;
    mb_state.settled = 0U;
    break;
}

if ((mb_state.mode == MB_BIAS) || (mb_state.mode == MB_HOLD)) {
    double propv[3];
    double prevv[3];
    double tv[3];
    old_integral = mb_state.integral_error_nms_s;
    prevv[0] = old_integral.x;
    prevv[1] = old_integral.y;
    prevv[2] = old_integral.z;
    propv[0] = old_integral.x + err.x * dt;
    propv[1] = old_integral.y + err.y * dt;
    propv[2] = old_integral.z + err.z * dt;
    for (i = 0; i < 3U; i++) {
        if (propv[i] > ilim) {
            propv[i] = ilim;
        } else if (propv[i] < -ilim) {
            propv[i] = -ilim;
        } else {
            propv[i] = propv[i];
        }
    }
    {
        double e[3];
        e[0] = err.x;
        e[1] = err.y;
        e[2] = err.z;
        mask = 0U;
        for (i = 0; i < 3U; i++) {
            double t_prop = -kp * e[i] - ki * propv[i];
            if (fabs(t_prop) > tlim) {
                mask |= (uint32_t)(1U << i);
            }
            if (t_prop > tlim) {
                double t_prev = -kp * e[i] - ki * prevv[i];
                if (t_prop > t_prev) {
                    propv[i] = prevv[i];
                }
            } else if (t_prop < -tlim) {
                double t_prev = -kp * e[i] - ki * prevv[i];
                if (t_prop < t_prev) {
                    propv[i] = prevv[i];
                }
            } else {
                propv[i] = propv[i];
            }
            tv[i] = -kp * e[i] - ki * propv[i];
            if (tv[i] > tlim) {
                tv[i] = tlim;
            } else if (tv[i] < -tlim) {
                tv[i] = -tlim;
            } else {
                tv[i] = tv[i];
            }
        }
    }
    proposed_integral = (adcs_vec3_t){propv[0], propv[1], propv[2]};
    torque = (adcs_vec3_t){tv[0], tv[1], tv[2]};
    mb_state.integral_error_nms_s = proposed_integral;
} else {
    double tv[3];
    tv[0] = -kp * err.x;
    tv[1] = -kp * err.y;
    tv[2] = -kp * err.z;
    for (i = 0; i < 3U; i++) {
        if (tv[i] > tlim) {
            tv[i] = tlim;
        } else if (tv[i] < -tlim) {
            tv[i] = -tlim;
        } else {
            tv[i] = tv[i];
        }
    }
    torque = (adcs_vec3_t){tv[0], tv[1], tv[2]};
    mask = 0U;
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
}

mb_output.mode = mb_state.mode;
mb_output.settled = mb_state.settled;
mb_output.saturation_mask = mask;
mb_output.momentum_nms = momentum;
mb_output.commanded_target_nms = mb_state.commanded_target_nms;
mb_output.error_nms = err;
mb_output.integral_error_nms_s = mb_state.integral_error_nms_s;
mb_output.torque_nm = torque;
